<?php declare(strict_types=1); ?>
<div class="page-heading"><span class="eyebrow">YOUR MONEY</span><h1>Salary</h1><p>Record what you receive and where it goes.</p></div>
<div class="money-summary"><div class="glass"><span>Salary this month</span><strong><?= number_format($income,2) ?></strong></div><div class="glass"><span>Expenses this month</span><strong><?= number_format($expense,2) ?></strong></div><div class="glass"><span>Remaining this month</span><strong><?= number_format($income-$expense,2) ?></strong></div></div>
<section class="glass form-panel"><h2>Add money entry</h2><form method="post" class="entry-form"><?php fields('salary','add_money'); ?><label>Type<select name="kind"><option value="salary">Salary received</option><option value="expense">Expense</option></select></label><label>Description<input name="label" maxlength="150" placeholder="Salary or expense" required></label><label>Amount<input name="amount" type="number" min="0.01" max="1000000000" step="0.01" placeholder="0.00" required></label><label>Date<input name="entry_date" type="date" value="<?= h($today) ?>" required></label><div class="submit-cell"><button class="button">Add entry</button></div></form></section>
<section class="glass list-box"><div class="section-head"><h2>History</h2><span class="muted"><?= count($money) ?> entries</span></div>
<?php if (!$money): ?><p class="empty">No entries yet. Start with your latest salary or expense.</p><?php else: foreach ($money as $entry): ?>
<div class="money-row"><div><strong><?= h($entry['label']) ?></strong><small><?= h(niceDate($entry['entry_date'])) ?> · <?= h(ucfirst($entry['kind'])) ?></small></div><span class="amount <?= h($entry['kind']) ?>"><?= $entry['kind']==='salary'?'+':'−' ?><?= number_format((float)$entry['amount'],2) ?></span><form method="post" data-confirm="Delete this entry?"><?php fields('salary','delete_money'); ?><input type="hidden" name="id" value="<?= (int)$entry['id'] ?>"><button class="mini danger">Delete</button></form></div>
<details class="edit-details"><summary>Edit entry</summary><form method="post" class="entry-form edit-money"><?php fields('salary','edit_money'); ?><input type="hidden" name="id" value="<?= (int)$entry['id'] ?>"><label>Type<select name="kind"><option value="salary" <?= $entry['kind']==='salary'?'selected':'' ?>>Salary received</option><option value="expense" <?= $entry['kind']==='expense'?'selected':'' ?>>Expense</option></select></label><label>Description<input name="label" maxlength="150" value="<?= h($entry['label']) ?>" required></label><label>Amount<input name="amount" type="number" min="0.01" max="1000000000" step="0.01" value="<?= h($entry['amount']) ?>" required></label><label>Date<input name="entry_date" type="date" value="<?= h($entry['entry_date']) ?>" required></label><div class="submit-cell"><button class="mini primary">Save changes</button></div></form></details>
<?php endforeach; endif; ?></section>
